// ===================================
// CONFIGURATION
// ===================================
const GOOGLE_MAPS_API_KEY = 'AIzaSyDPxA9a8qyRRhIzMVCR4n-vL2xEKqeC6no';
const MAX_DISTANZ_KM = $input.first().json.distanz || 25;

// Cache für Geocoding-Ergebnisse
const geocodeCache = {};

// ===================================
// GEOCODING FUNCTION
// ===================================
async function getCoordinates(address) {
  if (!address) return null;

  // Cache prüfen
  if (geocodeCache[address]) {
    return geocodeCache[address];
  }

  const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${GOOGLE_MAPS_API_KEY}`;

  try {
    const response = await fetch(url);
    const data = await response.json();

    if (data.status === 'OK' && data.results && data.results.length > 0) {
      const coords = {
        lat: data.results[0].geometry.location.lat,
        lng: data.results[0].geometry.location.lng
      };

      // Cache speichern
      geocodeCache[address] = coords;
      return coords;
    }
  } catch (error) {
    console.error(`Geocoding-Fehler für ${address}:`, error.message);
  }

  return null;
}

// ===================================
// DISTANCE CALCULATION (Haversine)
// ===================================
function calculateDistance(coord1, coord2) {
  const R = 6371; // Erdradius in km

  const toRad = (degrees) => degrees * (Math.PI / 180);

  const dLat = toRad(coord2.lat - coord1.lat);
  const dLon = toRad(coord2.lng - coord1.lng);

  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(coord1.lat)) * Math.cos(toRad(coord2.lat)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

// ===================================
// MAIN LOGIC
// ===================================
const items = $input.all();
const results = [];

// Ersten Input nehmen (merged data)
const firstItem = items[0].json;

// Kandidaten extrahieren (vom ersten Notion Node)
const kandidaten = [];
for (let i = 0; i < items.length; i++) {
  if (items[i].json.object === 'page' && items[i].json.parent?.database_id === 'b3f1eeab2d1a42f2a9ba9792568bc217') {
    kandidaten.push(items[i].json);
  }
}

// Fachgeschäfte extrahieren
const fachgeschaefte = [];
for (let i = 0; i < items.length; i++) {
  if (items[i].json.object === 'page' && items[i].json.parent?.database_id === 'c6d33fd30f924e6d87fe4cb9fdb2c2aa') {
    fachgeschaefte.push(items[i].json);
  }
}

// Arbeitgeber extrahieren
const arbeitgeber = [];
for (let i = 0; i < items.length; i++) {
  if (items[i].json.object === 'page' && items[i].json.parent?.database_id === '29a0974bd6228043850bf887c636d116') {
    arbeitgeber.push(items[i].json);
  }
}

console.log(`=== START ZUORDNUNG ===");
console.log(`Maximale Distanz: ${MAX_DISTANZ_KM} km`);
console.log(`Kandidaten: ${kandidaten.length}`);
console.log(`Fachgeschäfte: ${fachgeschaefte.length}`);
console.log(`Arbeitgeber: ${arbeitgeber.length}`);

if (kandidaten.length === 0) {
  console.log('✓ Keine Kandidaten ohne Zuordnung gefunden!');
  return [{ json: { message: 'Keine Kandidaten zu bearbeiten', count: 0 } }];
}

// Jeden Kandidaten verarbeiten
for (const kandidat of kandidaten) {
  const kandidatName = kandidat.properties?.Name?.title?.[0]?.plain_text || 'Unbekannt';
  const kandidatAdresse = kandidat.properties?.Wohnadresse?.rich_text?.[0]?.plain_text;

  if (!kandidatAdresse) {
    console.log(`✗ ${kandidatName}: Keine Adresse`);
    continue;
  }

  // Koordinaten des Kandidaten holen
  const kandidatCoords = await getCoordinates(kandidatAdresse);

  if (!kandidatCoords) {
    console.log(`✗ ${kandidatName}: Adresse nicht gefunden`);
    continue;
  }

  // Nächstes Fachgeschäft finden
  let nearestShop = null;
  let shortestDistance = Infinity;

  for (const shop of fachgeschaefte) {
    const shopAdresse = shop.properties?.['Adresse ']?.rich_text?.[0]?.plain_text;

    if (!shopAdresse) continue;

    const shopCoords = await getCoordinates(shopAdresse);

    if (!shopCoords) continue;

    const distance = calculateDistance(kandidatCoords, shopCoords);

    if (distance <= MAX_DISTANZ_KM && distance < shortestDistance) {
      nearestShop = {
        id: shop.id,
        name: shop.properties?.Name?.title?.[0]?.plain_text || 'Unbekannt',
        distance: distance
      };
      shortestDistance = distance;
    }
  }

  if (!nearestShop) {
    console.log(`✗ ${kandidatName}: Kein Geschäft innerhalb ${MAX_DISTANZ_KM} km`);
    continue;
  }

  // Distanz zum aktuellen Arbeitgeber berechnen
  let distanceToCurrentEmployer = null;

  const currentEmployerRelation = kandidat.properties?.['Aktueller Arbeitgeber']?.relation;

  if (currentEmployerRelation && currentEmployerRelation.length > 0) {
    const employerId = currentEmployerRelation[0].id;
    const employer = arbeitgeber.find(a => a.id === employerId);

    if (employer) {
      const employerAdresse = employer.properties?.['Adresse ']?.rich_text?.[0]?.plain_text;

      if (employerAdresse) {
        const employerCoords = await getCoordinates(employerAdresse);

        if (employerCoords) {
          distanceToCurrentEmployer = calculateDistance(kandidatCoords, employerCoords);
        }
      }
    }
  }

  // Ergebnis speichern
  results.push({
    json: {
      kandidat_id: kandidat.id,
      kandidat_name: kandidatName,
      shop_id: nearestShop.id,
      shop_name: nearestShop.name,
      distanz_shop: Math.round(nearestShop.distance * 10) / 10,
      distanz_aktueller_ag: distanceToCurrentEmployer ? Math.round(distanceToCurrentEmployer * 10) / 10 : null
    }
  });

  const employerInfo = distanceToCurrentEmployer 
    ? ` | Akt. AG: ${distanceToCurrentEmployer.toFixed(1)} km` 
    : '';

  console.log(`✓ ${kandidatName} → ${nearestShop.name} (${nearestShop.distance.toFixed(1)} km)${employerInfo}`);
}

console.log(`=== FERTIG! ${results.length} Kandidaten zugeordnet ===`);

if (results.length === 0) {
  return [{ json: { message: 'Keine Zuordnungen möglich', count: 0 } }];
}

return results;
